// The "no system ROM" message: drawn over the video (the VIC runs alone,
// showing its reset border colour) while the core has no ROM to start.
// Characters are 8x8 cells shown at twice their size.

module c65_norom (
	input  logic       clk,
	input  logic       ce_pix,     // one per pixel
	input  logic       hblank,
	input  logic       vblank,
	input  logic       enable,
	input  logic [7:0] r_in, g_in, b_in,
	output logic [7:0] r, g, b
);

localparam COLS = 38, ROWS = 12;
localparam X0 = 48, Y0 = 64;     // top left corner of the text, in output pixels

logic [10:0] px, py;
logic        hb_d;
always_ff @(posedge clk) begin
	if (ce_pix) begin
		hb_d <= hblank;
		if (hblank) px <= '0; else px <= px + 11'd1;
		if (vblank) py <= '0;
		else if (hblank && !hb_d) py <= py + 11'd1;
	end
end

// text position: each character cell is 16x16 output pixels
wire [10:0] tx = px - 11'(X0);
wire [10:0] ty = py - 11'(Y0);
wire        in_text = (px >= 11'(X0)) && (py >= 11'(Y0)) && (tx[10:4] < 7'(COLS)) && (ty[10:4] < 7'(ROWS));

