// one pipeline stage: look the pixel up, then mix it in
logic       dot;
logic [7:0] r_d, g_d, b_d;
always_ff @(posedge clk) begin
	logic [7:0] row;
	row = glyph(char_at(ty[7:4], tx[9:4]), ty[3:1]);
	dot <= enable && in_text && row[3'd7 - tx[3:1]];
	r_d <= r_in; g_d <= g_in; b_d <= b_in;
end

assign r = dot ? 8'hFF : r_d;
assign g = dot ? 8'hFF : g_d;
assign b = dot ? 8'hFF : b_d;

endmodule
